import SwiftUI

private let accent=Color(red:0.48,green:0.7,blue:0.98)
private let background=Color(red:0.025,green:0.047,blue:0.08)
@main struct PS5LibraryApp:App {
    @StateObject private var store=Store()
    var body:some Scene{WindowGroup{RootView().environmentObject(store).preferredColorScheme(.dark).tint(accent)}}
}
struct ArtworkView:View {
    @EnvironmentObject var store:Store;let path:String;@State private var image:UIImage?
    var body:some View{ZStack{background;Image(systemName:"gamecontroller.fill").font(.largeTitle).foregroundStyle(accent.opacity(0.4));if let image=image{Image(uiImage:image).resizable().scaledToFill()}}
        .clipped().task(id:(store.account?.id ?? "")+path){image=nil;guard let api=store.api else{return};do{let data=try await api.artwork(path);let decoded=await Task.detached(priority:.utility){UIImage(data:data)?.preparingForDisplay()}.value;if !Task.isCancelled{image=decoded}}catch{}}
    }
}
struct RootView:View {
    @EnvironmentObject var store:Store;@State private var query="";@State private var addAccount=false
    var body:some View{Group{if store.account==nil{SignIn()}else{TabView{
        NavigationStack{ScrollView{VStack(alignment:.leading,spacing:26){if store.offline{Label("Server offline · showing last synced data",systemImage:"wifi.slash").font(.caption).foregroundStyle(.orange)}
            if query.isEmpty,let hero=store.data.featured,let game=store.data.games.first(where:{$0.id==hero.gameId}){NavigationLink(value:game){ZStack(alignment:.bottomLeading){ArtworkView(path:hero.heroUrl ?? game.heroUrl).frame(height:350);LinearGradient(colors:[.clear,background],startPoint:.top,endPoint:.bottom);VStack(alignment:.leading,spacing:9){Text("FEATURED").font(.caption).tracking(3).foregroundStyle(accent);Text(game.title).font(.largeTitle.bold());Text(game.description ?? "").lineLimit(2).font(.subheadline).foregroundStyle(.secondary);Text("View Game  ›").font(.headline)}.padding(22)}}.buttonStyle(.plain).clipShape(RoundedRectangle(cornerRadius:20))}
            Text(query.isEmpty ? "Recently Added":"Search Results").font(.title2.bold());GameGrid(games:store.data.games.filter{query.isEmpty||($0.title+" "+($0.publisher ?? "")+" "+($0.genres ?? []).joined(separator:" ")).localizedCaseInsensitiveContains(query)})
            if store.loading{ProgressView("Loading your library…").frame(maxWidth:.infinity)}
        }.padding()}.background(background).navigationTitle("PS5Library").searchable(text:$query,prompt:"Games, publishers, genres").navigationDestination(for:Game.self){GameDetails(game:$0)}.refreshable{await store.refresh()}}
        .tabItem{Label("Discover",systemImage:"sparkles")}
        NavigationStack{ScrollView{VStack(alignment:.leading){ConsolePicker();GameGrid(games:store.data.games.filter{store.ready($0)});if store.offline{Text("Availability is from the last console report.").foregroundStyle(.orange)}}.padding()}.navigationTitle("My Library").navigationDestination(for:Game.self){GameDetails(game:$0)}.refreshable{await store.refresh()}}.tabItem{Label("Library",systemImage:"square.grid.2x2")}
        NavigationStack{ScrollView{LazyVStack(spacing:18){ForEach(store.data.jobs){JobCard(job:$0)};if store.data.jobs.isEmpty{ContentUnavailableView("You're all caught up",systemImage:"checkmark.circle",description:Text("Downloads keep running on your server when you close the companion."))}}.padding()}.navigationTitle("Downloads").refreshable{await store.refresh()}}.tabItem{Label("Downloads",systemImage:"arrow.down.circle")}
        NavigationStack{ConsolesView().navigationTitle("My PS5s")}.tabItem{Label("My PS5",systemImage:"gamecontroller")}
        NavigationStack{Form{Section("Your accounts"){ForEach(store.accounts){profile in Button{store.activate(profile)}label:{HStack{VStack(alignment:.leading){Text(profile.username);Text(profile.server.host ?? "").font(.caption)};Spacer();if profile.id==store.account?.id{Image(systemName:"checkmark")}}}};Button("Add account / server"){addAccount=true};Button("Sign out",role:.destructive){store.signOut()}}
            Section{NavigationLink("Prepared packages on this server"){CacheView()};if store.account?.role=="ADMIN"{InvitationView()}}
            Section{Text("Independent homebrew library. Sony/PSN credentials are never required.").font(.footnote).foregroundStyle(.secondary)}
        }.navigationTitle("Settings")}.tabItem{Label("Settings",systemImage:"gearshape")}
    }}}
    .sheet(isPresented:$addAccount){SignIn()}.alert("PS5Library",isPresented:Binding(get:{store.error != nil},set:{if !$0{store.error=nil}})){Button("OK"){store.error=nil}}message:{Text(store.error ?? "")}
    }
}
struct GameGrid:View{let games:[Game];var body:some View{LazyVGrid(columns:[GridItem(.adaptive(minimum:145),spacing:15)],spacing:22){ForEach(games){game in NavigationLink(value:game){VStack(alignment:.leading,spacing:8){ArtworkView(path:game.coverUrl).aspectRatio(3/4,contentMode:.fit).clipShape(RoundedRectangle(cornerRadius:13));Text(game.title).font(.headline).lineLimit(2)}}.buttonStyle(.plain)}}}}
struct GameDetails:View {
    @EnvironmentObject var store:Store;let game:Game;@State private var download=false
    var body:some View{ScrollView{VStack(alignment:.leading,spacing:22){ArtworkView(path:game.heroUrl).frame(height:260).overlay(alignment:.bottom){LinearGradient(colors:[.clear,background],startPoint:.top,endPoint:.bottom).frame(height:120)};VStack(alignment:.leading,spacing:18){Text(game.title).font(.largeTitle.bold());Text((game.genres ?? []).joined(separator:" · ")).foregroundStyle(accent);if store.ready(game){Label("Available on your PS5",systemImage:"checkmark.circle.fill").foregroundStyle(accent)};Button("Download & Prepare"){download=true}.buttonStyle(.borderedProminent).controlSize(.large).disabled(game.releases.allSatisfy{$0.sources.isEmpty});Text(game.description ?? "Description unavailable.");Text(game.publisher ?? "").font(.caption).foregroundStyle(.secondary);Text("Available releases").font(.title2.bold());ForEach(game.releases){release in HStack{Text(readable(release.kind));Spacer();Text(release.version);Text(bytes(release.size ?? 0)).foregroundStyle(.secondary)}.font(.subheadline)}.padding(.horizontal);ScrollView(.horizontal){HStack{ForEach(game.screenshotUrls ?? [],id:\.self){ArtworkView(path:$0).frame(width:290,height:164).clipShape(RoundedRectangle(cornerRadius:12))}}.padding()}}}.background(background).navigationBarTitleDisplayMode(.inline).sheet(isPresented:$download){InstallationView(game:game)}}
}
struct ConsolePicker:View{@EnvironmentObject var store:Store;var body:some View{Picker("Target PS5",selection:$store.data.consoleId){ForEach(store.data.consoles){Text($0.name+" · "+readable($0.presence)).tag($0.id)}}.onChange(of:store.data.consoleId){_,_ in Task{await store.refresh()}}}}
struct InstallationView:View {
    @EnvironmentObject var store:Store;@Environment(\.dismiss) var dismiss;let game:Game
    @State private var releaseId="",consoleId="",storageId="",method="";@State private var plan:Plan?;@State private var busy=false;@State private var failure:String?
    var release:Release?{game.releases.first{$0.id==releaseId}}
    var body:some View{NavigationStack{Form{Section{HStack{ArtworkView(path:game.coverUrl).frame(width:75,height:100).clipShape(RoundedRectangle(cornerRadius:8));Text(game.title).font(.headline)}}
        Section("1 · Version"){Picker("Release",selection:$releaseId){ForEach(game.releases){Text(readable($0.kind)+" · "+$0.version).tag($0.id)}}}
        Section("2 · Your PS5"){Picker("Console",selection:$consoleId){ForEach(store.data.consoles){Text($0.name+" · "+readable($0.presence)).tag($0.id)}}}
        if let plan=plan{Section("3 · Storage"){Picker("Destination",selection:$storageId){ForEach(plan.storage.filter{$0.allowed}){Text($0.displayName+" · "+bytes($0.freeBytes)+" free").tag($0.id)}};if plan.storage.allSatisfy({!$0.allowed}){Text("No supported destination has enough free space.").foregroundStyle(.orange)}}
            Section("4 · Installation method"){Picker("Method",selection:$method){ForEach(plan.methods,id:\.self){Text($0=="SHADOWMOUNT" ? "ShadowMountPlus":$0=="HOMEBREW" ? "Homebrew":$0).tag($0)}}}
            Section("5 · Confirm"){Label(readable(plan.compatibility.status),systemImage:plan.allowed ? "checkmark.shield":"exclamationmark.triangle").foregroundStyle(plan.allowed ? accent:.orange);if let storage=plan.storage.first(where:{$0.id==storageId}){Text((plan.estimated ? "Estimated space required: ":"Space required: ")+bytes(storage.requiredBytes))};if !plan.online{Text("Preparation can start now. Delivery will wait for your PS5.")};Button("Download & Prepare"){confirm()}.disabled(!plan.allowed||storageId.isEmpty||busy)}
        }else{ProgressView("Checking your PS5 and compatibility…")};if let failure=failure{Text(failure).foregroundStyle(.orange)}
    }.navigationTitle("Download").toolbar{ToolbarItem(placement:.cancellationAction){Button("Cancel"){dismiss()}}}
    .onAppear{releaseId=game.releases.first?.id ?? "";consoleId=store.data.consoleId}
    .task(id:releaseId+consoleId+method){await loadPlan()}
    }
    func loadPlan() async{guard let api=store.api,let source=release?.sources.first,!consoleId.isEmpty else{return};failure=nil;do{var body=["sourceReleaseId":source.id,"consoleId":consoleId];if !method.isEmpty{body["method"]=method};let result:Plan=try await api.request("/installations/plan",method:"POST",json:body);guard !Task.isCancelled else{return};plan=result;if method.isEmpty{method=result.method};if !result.storage.contains(where:{$0.id==storageId&&$0.allowed}){storageId=result.storage.first(where:{$0.allowed})?.id ?? ""}}catch{if !Task.isCancelled{plan=nil;failure=error.localizedDescription}}}
    func confirm(){guard let source=release?.sources.first,let api=store.api else{return};busy=true;Task{do{let _:Acknowledgement=try await api.request("/installations",method:"POST",json:["sourceReleaseId":source.id,"consoleId":consoleId,"storageId":storageId,"method":method]);await store.refresh();dismiss()}catch{failure=error.localizedDescription};busy=false}}
}
struct JobCard:View {
    @EnvironmentObject var store:Store;let job:Job
    var body:some View{VStack(alignment:.leading,spacing:14){HStack{if let game=store.data.games.first(where:{$0.releases.contains(where:{$0.id==job.releaseId})}){ArtworkView(path:game.coverUrl).frame(width:72,height:92).clipShape(RoundedRectangle(cornerRadius:8))};VStack(alignment:.leading){Text(job.title ?? "Selected release").font(.headline);Text(readable(job.state)).foregroundStyle(accent);if let console=store.data.consoles.first(where:{$0.id==job.consoleId}){Text(console.name).font(.caption);Text(console.storage.first(where:{$0.id==job.storageId})?.displayName ?? "").font(.caption).foregroundStyle(.secondary)}}
        if job.kind=="BUILD"&&job.state != "DOWNLOADING"{if job.state=="COMPLETED"{Label("Prepared and verified",systemImage:"checkmark.circle")}else if job.state != "ERROR"{ProgressView()};Text(job.progress?.stage ?? readable(job.state)).font(.caption)}else{ProgressView(value:job.totalBytes.flatMap{$0>0 ? Double(job.downloadedBytes)/Double($0):nil});Text(bytes(job.downloadedBytes)+" / "+bytes(job.totalBytes ?? 0)).font(.caption.monospacedDigit());if job.speedBytesPerSecond>0{Text(bytes(job.speedBytesPerSecond)+"/s"+(job.etaSeconds.map{" · About \($0/60)m \($0%60)s"} ?? "")).font(.caption).foregroundStyle(.secondary)}}
        if let error=job.error{Text(readable(error)).foregroundStyle(.orange)}
        if job.kind=="DOWNLOAD" && !["COMPLETED","CANCELLED"].contains(job.state){HStack{Button(job.state=="PAUSED" ? "Resume":job.state=="ERROR" ? "Retry":"Pause"){control(job.state=="PAUSED" ? "resume":job.state=="ERROR" ? "retry":"pause")};Button("Cancel",role:.destructive){control("cancel")}}}
    }.padding(18).frame(maxWidth:.infinity,alignment:.leading).background(.ultraThinMaterial,in:RoundedRectangle(cornerRadius:20))}
    func control(_ action:String){store.perform{api in let _:Acknowledgement=try await api.request("/jobs/\(job.id)/control",method:"POST",json:["action":action])}}
}
struct ConsolesView:View {
    @EnvironmentObject var store:Store;@State private var code="";@State private var rename="";@State private var editing:Console?
    var body:some View{List{Section("Pair a console"){TextField("Code shown on PS5",text:$code).textInputAutocapitalization(.characters).autocorrectionDisabled();Button("Link to my account"){let value=code;store.perform{api in let _:Acknowledgement=try await api.request("/pairings/claim",method:"POST",json:["code":value])};code=""}.disabled(code.count != 10)}
        ForEach(store.data.consoles){console in Section{VStack(alignment:.leading,spacing:16){HStack{Image(systemName:"gamecontroller.fill").foregroundStyle(accent);Text(console.name).font(.title3.bold());Spacer();Circle().fill(console.presence=="ONLINE" ? .green:.gray).frame(width:9,height:9)};Text(readable(console.presence)+" · Firmware "+(console.firmware ?? "unknown")+" · \(console.games) games").font(.caption);ForEach(console.storage){storage in VStack(alignment:.leading){Text(storage.displayName);ProgressView(value:storage.totalBytes>0 ? Double(storage.totalBytes-storage.freeBytes)/Double(storage.totalBytes):0);Text(bytes(storage.freeBytes)+" available").font(.caption).foregroundStyle(.secondary)}};Button("Rename"){editing=console;rename=console.name}}.padding(.vertical,8)}}}.refreshable{await store.refresh()}.alert("Console name",isPresented:Binding(get:{editing != nil},set:{if !$0{editing=nil}})){TextField("Name",text:$rename);Button("Save"){if let id=editing?.id{let name=rename;store.perform{api in let _:Acknowledgement=try await api.request("/consoles/\(id)",method:"PATCH",json:["name":name])}};editing=nil};Button("Cancel",role:.cancel){editing=nil}}}
}
struct CacheView:View{@EnvironmentObject var store:Store;@State private var artifacts:[Artifact]=[];var body:some View{List{Section{Text("Verified packages stay on your PC for reuse. Deleting a cached copy keeps the original source and your console's copy.").font(.footnote)};ForEach(artifacts){artifact in VStack(alignment:.leading){Text(artifact.title).font(.headline);Text(artifact.version+" · "+bytes(artifact.size)).font(.caption)}.swipeActions{Button("Delete PC copy",role:.destructive){store.perform{api in let _:Acknowledgement=try await api.request("/artifacts/\(artifact.id)",method:"DELETE");artifacts=try await api.request("/artifacts")}}}}.navigationTitle("Server cache").task{guard let api=store.api else{return};do{artifacts=try await api.request("/artifacts")}catch{store.error=error.localizedDescription}}}}
struct InvitationView:View{@EnvironmentObject var store:Store;@State private var invitation="";var body:some View{Button("Create invitation for a friend"){store.perform{api in let response:Invitation=try await api.request("/admin/invites",method:"POST");invitation=response.token}};if !invitation.isEmpty{Text("Single use · expires in 7 days").font(.caption);Text(invitation).font(.caption.monospaced()).textSelection(.enabled)}}}
struct SignIn:View{
    @EnvironmentObject var store:Store;@Environment(\.dismiss) var dismiss;@State private var server="",username="",password="",invite="";@State private var register=false,busy=false;@State private var failure:String?
    var body:some View{NavigationStack{ScrollView{VStack(alignment:.leading,spacing:24){Image(systemName:"gamecontroller.fill").font(.system(size:48)).foregroundStyle(accent);Text("PS5Library").font(.largeTitle.bold());Text("Games without limits").foregroundStyle(.secondary);TextField("https://your-library.example",text:$server).keyboardType(.URL).textInputAutocapitalization(.never).autocorrectionDisabled();TextField("Username",text:$username).textInputAutocapitalization(.never).autocorrectionDisabled().textContentType(.username);SecureField("Password",text:$password).textContentType(register ? .newPassword:.password);if register{TextField("Invitation code",text:$invite).textInputAutocapitalization(.never).autocorrectionDisabled()};if let failure=failure{Text(failure).foregroundStyle(.orange)};Button(register ? "Create account":"Sign in"){busy=true;Task{do{try await store.login(server:server,username:username,password:password,invite:invite,register:register);dismiss()}catch{failure=error.localizedDescription};password="";busy=false}}.buttonStyle(.borderedProminent).controlSize(.large).disabled(busy||username.isEmpty||password.isEmpty);Button(register ? "Already have an account?":"Have a friend's invitation?"){register.toggle()};Text("Your server. Your account. Only your consoles and library.").font(.footnote).foregroundStyle(.secondary)}.textFieldStyle(.roundedBorder).padding(28)}}}
}
